64. fn mock_flow_path(dir: &Path) -> TestResult<PathBuf> {
65.     let bin_dir = dir.join("flow-bin");
66.     fs::create_dir(&bin_dir)?;
67.     write_executable(
68.         &bin_dir.join("claude"),
69.         r#"#!/bin/sh
70. # The prompt is always the last argument; flags like --print, --output-format,
71. # --dangerously-skip-permissions etc. precede it.
72. prompt=""
73. for arg in "$@"; do prompt="$arg"; done
74. # For specify, derrick pre-scaffolds the feature dir and amends the prompt
75. # with `Write the spec to: specs/<NNN>-<slug>/spec.md`. Extract that path so
76. # the mock writes to the same location derrick expects.
77. target=$(printf '%s' "$prompt" | /usr/bin/awk '/Write the spec to:/ { for (i=1;i<=NF;i++) if ($i ~ /^specs\//) { sub(/\/spec\.md$/, "", $i); print $i; exit } }')
78. if [ -z "$target" ]; then
79.   # Plan/tasks/etc — read feature.json for the feature dir.
80.   if [ -f .specify/feature.json ]; then
81.     target=$(/usr/bin/sed -n 's/.*"feature_directory"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/p' .specify/feature.json | /usr/bin/head -1)
82.   fi
83. fi
84. if [ -z "$target" ]; then target="specs/001-test"; fi
85. /bin/mkdir -p "$target" .specify
86. case "$prompt" in
87.   *speckit.specify*)
88.     printf '{"feature_directory":"%s"}' "$target" > .specify/feature.json
89.     printf 'spec' > "$target/spec.md"
90.     printf 'ok'
91.     ;;
92.   *speckit.plan*)
93.     printf 'plan' > "$target/plan.md"
94.     printf 'ok'
95.     ;;
96.   *speckit.tasks*)
97.     printf 'tasks' > "$target/tasks.md"
98.     printf 'ok'
99.     ;;
100.   *Verdict*|*Plan:*)
101.     # D37 codex-fallback: assay invokes the claude host instead of codex
102.     # in non-TTY contexts. Mirror the codex mock's verdict output.
103.     printf '## Verdict\naccept\n'
104.     ;;
105.   *)
106.     printf 'ok'
107.     ;;
108. esac
109. "#,
110.     )?;
111.     write_executable(
112.         &bin_dir.join("codex"),
113.         r#"#!/bin/sh
114. printf '## Verdict\naccept\n'
115. "#,
116.     )?;
117.     Ok(bin_dir)
